INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2039861, 277005, 13719, '<td valign="top">cool shot</td>', 'cool shot', '2006-01-16 00:06:21.000000', NULL, 1),
(2039869, 280799, 13719, '<td valign="top">cool shot.... thats gonna hurt</td>', 'cool shot.... thats gonna hurt', '2006-01-16 00:07:21.000000', NULL, 1),
(2039901, 275862, 70, '<td valign="top">My first full view while wading through the thumbnails. I just love this. The softness is great. The whole feeling is kind of ethereal. It''d be nice if the horses would face you but I know how that works. We always jokes about having a Butts of the Animal Kingdom photo book - they aren''t too prone to cooperating. Nice pick.</td>', 'My first full view while wading through the thumbnails. I just love this. The softness is great. The whole feeling is kind of ethereal. It''d be nice if the horses would face you but I know how that works. We always jokes about having a Butts of the Animal Kingdom photo book - they aren''t too prone to cooperating. Nice pick.', '2006-01-16 00:12:14.000000', NULL, 1),
(2039907, 281983, 43671, '<td valign="top">Amazing shot for real, hope it ribbons for you. The colors are sweet.</td>', 'Amazing shot for real, hope it ribbons for you. The colors are sweet.', '2006-01-16 00:13:19.000000', NULL, 1),
