(2040563, 279920, 43930, '<td valign="top">A little more saturation may add more impact to the wonderful colors here... did you use a polarizer?</td>', 'A little more saturation may add more impact to the wonderful colors here... did you use a polarizer?', '2006-01-16 01:54:08.000000', NULL, 1),
(2040564, 275921, 39349, '<td valign="top">Great perspective! Well done.</td>', 'Great perspective! Well done.', '2006-01-16 01:54:15.000000', NULL, 1),
(2040565, 281836, 51359, '<td valign="top">Very mystical, great moody colouring.</td>', 'Very mystical, great moody colouring.', '2006-01-16 01:54:19.000000', NULL, 1),
