(2045838, 281892, 26313, '<td valign="top">I''m betting this is getting hammered, but I really like it.</td>', 'I''m betting this is getting hammered, but I really like it.', '2006-01-16 23:16:11.000000', NULL, 1),
(2045839, 274981, 38915, '<td valign="top">nice</td>', 'nice', '2006-01-16 23:16:13.000000', NULL, 1),
(2045843, 275753, 26313, '<td valign="top">Wow. Awesome cloud detail. Like the composition too.</td>', 'Wow. Awesome cloud detail. Like the composition too.', '2006-01-16 23:17:07.000000', NULL, 1),
