(2045876, 282005, 46479, '<td valign="top">I love your picture!</td>', 'I love your picture!', '2006-01-16 23:28:17.000000', NULL, 1),
(2045877, 282008, 26313, '<td valign="top">I would have liked to see the entire bike, and maybe the rest of the ring too. Flowers are a neat touch--I think they add a lot to it.</td>', 'I would have liked to see the entire bike, and maybe the rest of the ring too. Flowers are a neat touch--I think they add a lot to it.', '2006-01-16 23:28:48.000000', NULL, 1),
