(2047523, 281326, 43774, '<td valign="top">Looks out of focus, would be better if the dividing line between land and sky were not so centered.</td>', 'Looks out of focus, would be better if the dividing line between land and sky were not so centered.', '2006-01-17 10:11:58.000000', NULL, 1),
(2047524, 276836, 43774, '<td valign="top">Looks out of focus</td>', 'Looks out of focus', '2006-01-17 10:12:06.000000', NULL, 1),
(2047525, 279649, 26464, '<td valign="top">great sports shot</td>', 'great sports shot', '2006-01-17 10:12:10.000000', NULL, 1),
