(2047527, 276240, 43774, '<td valign="top">Over exposed, not fond of the processing.</td>', 'Over exposed, not fond of the processing.', '2006-01-17 10:12:33.000000', NULL, 1),
(2047528, 278083, 43774, '<td valign="top">Photo is out of focus</td>', 'Photo is out of focus', '2006-01-17 10:12:40.000000', NULL, 1),
(2047529, 281854, 46634, '<td valign="top">What a goofy looking Gerbil.<br/> <br/> <br/>His expression is great. He seems to be concentrating on something and at any moment I expect him to pounce. Good shot</td>', 'What a goofy looking Gerbil.  His expression is great. He seems to be concentrating on something and at any moment I expect him to pounce. Good shot', '2006-01-17 10:12:41.000000', NULL, 1),
(2047530, 279771, 43774, '<td valign="top">Not fond of the grain or focus.</td>', 'Not fond of the grain or focus.', '2006-01-17 10:12:42.000000', NULL, 1),
