(2056166, 274852, 36762, '<td valign="top">This reminds me of a Thomas Kinkade painting. Great job.</td>', 'This reminds me of a Thomas Kinkade painting. Great job.', '2006-01-18 21:03:19.000000', NULL, 1),
(2056171, 281505, 2780, '<td valign="top">I really like the symmetry and the lovely tropical colours here. Very peaceful looking shot.</td>', 'I really like the symmetry and the lovely tropical colours here. Very peaceful looking shot.', '2006-01-18 21:03:47.000000', NULL, 1),
(2056174, 276052, 93, '<td valign="top">Eyes are just a *little* too hyper-realistic for my tastes.  Even with contacts, that''s just too metallic.  It''s a nice unique portrait though, and good B&amp;W conversion.</td>', 'Eyes are just a *little* too hyper-realistic for my tastes.  Even with contacts, that''s just too metallic.  It''s a nice unique portrait though, and good B&W conversion.', '2006-01-18 21:04:04.000000', NULL, 1),
