(2056376, 276859, 93, '<td valign="top">Very very busy photo with no real focal point.  Just too chaotic.</td>', 'Very very busy photo with no real focal point.  Just too chaotic.', '2006-01-18 21:50:28.000000', NULL, 1),
(2056378, 277667, 3306, '<td valign="top">Nice shot. Maybe a bit oversaturated.</td>', 'Nice shot. Maybe a bit oversaturated.', '2006-01-18 21:51:18.000000', NULL, 1),
(2056381, 281484, 3306, '<td valign="top">Well done composition</td>', 'Well done composition', '2006-01-18 21:51:52.000000', NULL, 1),
(2056383, 281959, 93, '<td valign="top">One of the most interesting photos of a mason jar I''ve ever seen.  Dark and moody, and some great selective lighting.  Nice job.  Not sure that it''s the best pick for DPC, but *I* like it a lot.</td>', 'One of the most interesting photos of a mason jar I''ve ever seen.  Dark and moody, and some great selective lighting.  Nice job.  Not sure that it''s the best pick for DPC, but *I* like it a lot.', '2006-01-18 21:52:11.000000', NULL, 1),
(2056387, 280942, 93, '<td valign="top">Some good use of backlighting, but the red in her skin tones could have been easily fixed in post, and leave her looking feverish.  The focus seems just a little too forward of her face as well.</td>', 'Some good use of backlighting, but the red in her skin tones could have been easily fixed in post, and leave her looking feverish.  The focus seems just a little too forward of her face as well.', '2006-01-18 21:53:08.000000', NULL, 1),
(2056389, 281362, 3306, '<td valign="top">Wonderfully composed. Most people would not have seen the beauty in this capture. You have an excellent eye.</td>', 'Wonderfully composed. Most people would not have seen the beauty in this capture. You have an excellent eye.', '2006-01-18 21:53:27.000000', NULL, 1),
(2056391, 277764, 93, '<td valign="top">Love the rainbow. A nice, happy, whimsical photo.  Perhaps a touch oversaturated in areas, but it''s fun.</td>', 'Love the rainbow. A nice, happy, whimsical photo.  Perhaps a touch oversaturated in areas, but it''s fun.', '2006-01-18 21:54:14.000000', NULL, 1),
(2056393, 277958, 3306, '<td valign="top">I really liked the original and I like this one as well. Great job.</td>', 'I really liked the original and I like this one as well. Great job.', '2006-01-18 21:54:39.000000', NULL, 1),
(2056396, 275522, 93, '<td valign="top">Very whimsical. (that''s my new word).  It''s very "painting" like, and I think maybe the contrast could have been slightly stronger.</td>', 'Very whimsical. (that''s my new word).  It''s very "painting" like, and I think maybe the contrast could have been slightly stronger.', '2006-01-18 21:55:29.000000', NULL, 1),
