(2060693, 279601, 2780, '<td valign="top">I think this would look great in B&amp;W with the rainbow in colour.</td>', 'I think this would look great in B&W with the rainbow in colour.', '2006-01-19 18:30:48.000000', NULL, 1),
(2060696, 275343, 2780, '<td valign="top">I love the colours and the reflections here, fantastic shot.</td>', 'I love the colours and the reflections here, fantastic shot.', '2006-01-19 18:31:04.000000', NULL, 1),
