(2060772, 275932, 24486, '<td valign="top">I think this is probably the most unique dpc droplet photograph ever.</td>', 'I think this is probably the most unique dpc droplet photograph ever.', '2006-01-19 18:50:54.000000', NULL, 1),
(2060774, 281184, 24486, '<td valign="top">A really excellant effect</td>', 'A really excellant effect', '2006-01-19 18:51:20.000000', NULL, 1),
