(2069751, 276082, 46468, '<td valign="top">Beautiful memory captured. The lighting on her is great, she is precious. I would have preferred a sharper focus on her face and maybe from just a slightly higher angle, of course that is only my opinion</td>', 'Beautiful memory captured. The lighting on her is great, she is precious. I would have preferred a sharper focus on her face and maybe from just a slightly higher angle, of course that is only my opinion', '2006-01-22 01:30:04.000000', NULL, 1),
(2069756, 281595, 46468, '<td valign="top">Lovely capture, such joy expressed from the littlest one. The focus seems just the tiniest bit soft, but maybe that is what you were looking for. Nicely done</td>', 'Lovely capture, such joy expressed from the littlest one. The focus seems just the tiniest bit soft, but maybe that is what you were looking for. Nicely done', '2006-01-22 01:32:04.000000', NULL, 1),
(2069757, 275753, 16197, '<td valign="top">Very Nice Endeed.</td>', 'Very Nice Endeed.', '2006-01-22 01:32:32.000000', NULL, 1),
