(2070846, 280450, 45754, '<td valign="top">Nice lighting and emotion.</td>', 'Nice lighting and emotion.', '2006-01-22 12:59:30.000000', NULL, 1),
(2070847, 280582, 24212, '<td valign="top">Subtle, yet with strong lines. I particularly like the softness of the tree branches in the mist.</td>', 'Subtle, yet with strong lines. I particularly like the softness of the tree branches in the mist.', '2006-01-22 12:59:35.000000', NULL, 1),
(2070850, 275282, 45754, '<td valign="top">LOLOL very funny!</td>', 'LOLOL very funny!', '2006-01-22 13:00:17.000000', NULL, 1),
