(2089663, 275391, 11738, '<td valign="top">I wish his eyes were brighter.</td>', 'I wish his eyes were brighter.', '2006-01-26 19:48:37.000000', NULL, 1),
(2089666, 281896, 11738, '<td valign="top">Sweetness.  Awesome capture.  Worth getting up early to capture that.  Well done.</td>', 'Sweetness.  Awesome capture.  Worth getting up early to capture that.  Well done.', '2006-01-26 19:49:25.000000', NULL, 1),
(2089678, 280022, 40245, '<td valign="top">I hope people have thieir monitors calibrated. Easy to miss the pink without the title. Perphaps you could have saturated it a bit more to give it emphasis. Sets a lovely mood though.</td>', 'I hope people have thieir monitors calibrated. Easy to miss the pink without the title. Perphaps you could have saturated it a bit more to give it emphasis. Sets a lovely mood though.', '2006-01-26 19:51:39.000000', NULL, 1),
(2089687, 274784, 11738, '<td valign="top">Rocks and tree truck could have been just a tad brighter.  Very nice composition.</td>', 'Rocks and tree truck could have been just a tad brighter.  Very nice composition.', '2006-01-26 19:52:58.000000', NULL, 1),
(2089697, 274727, 11738, '<td valign="top">Love her expression.  I like the image treatment although i wish the highlights weren''t so close to being blown out.</td>', 'Love her expression.  I like the image treatment although i wish the highlights weren''t so close to being blown out.', '2006-01-26 19:54:25.000000', NULL, 1),
