(2098039, 274643, 27845, '<td valign="top">Good title. Excellent picture. 10. Fav.</td>', 'Good title. Excellent picture. 10. Fav.', '2006-01-29 10:44:38.000000', NULL, 1),
(2098040, 274651, 30508, '<td valign="top">Sweet!  I really like the pattern and texture on the ground and the way the skateboard and kid are perfectly silhouetted against it.</td>', 'Sweet!  I really like the pattern and texture on the ground and the way the skateboard and kid are perfectly silhouetted against it.', '2006-01-29 10:45:16.000000', NULL, 1),
(2098042, 277879, 30508, '<td valign="top">Ahhh, Venice.  Wonderful image.  I love the colored boats and the way they draw the eye into the composition.  The bridge in the upper left adds a nice secondary focal point.  Great colors and textures.</td>', 'Ahhh, Venice.  Wonderful image.  I love the colored boats and the way they draw the eye into the composition.  The bridge in the upper left adds a nice secondary focal point.  Great colors and textures.', '2006-01-29 10:47:13.000000', NULL, 1),
